  ('8833068b-cff1-4351-8ee3-1b959a1e903d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हालाँकि मैं यह मानती हूँ कि संगीत में वह असीम शक््‍तति है कि कुछ अप्रत््ययाशित वह जरूर रच देता है, जिसका अनुभव भी कई बार हमें हुआ है। कई बार अपने बाबा पंडित दीनानाथ मंगेशकर को सुनते हुए भी मैं कुछ अप्रत््ययाशित अनुभव करती थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2bdd621f-18a1-43d5-a34f-8b09a0262813', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यह मैं उन कोरस गाने वाली लड़कियोों की बात कर रही हूँ, जो बहुत शुरुआती दौर में लगभग पचास और साठ के दशक में संगीतकारों के यहाँ कोरस गाने के लिए जाती रही हैं। आजकल का मुझे कुछ मालूम नहीं है। अब कौन-कौन से लोग हैं और उनका सिंगर््स के साथ में गाना रेकॉर््ड होता है या अलग से? यह मुझे मालूम नहीं है। मुझसे मिलने वाले जितने लड़के और लड़कियाँ थीं, उन सबने बहुत बाद तक संपर््क बनाया हुआ था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('105269f7-ef67-4cb3-acac-1d72c4197c4c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आपको एक वाकया बताती हूँ। मैं मुंबई में उस््तताद अली अकबर खाँ और पंडित रविशंकर का एक कंसर््ट सुन रही थी। मैं श्रोताओं की पंक््‍तति में बिल्कुल आगे बैठी अली अकबर भाई का वादन सुन रही थी और वे अत््यंत मंत्रमुग्ध किस््म का वादन कर रहे थे। तभी कुछ समय बीता होगा, मसलन पचास-साठ मिनट कि ‘ठन’ से उनके सरोद का एक तार टूटा और उन््हें बजाना बंद करना पड़ा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('50b50485-bddb-4f17-a137-c1eb30904bd5', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जब वे उठकर पीछे ग्रीन रूम में गए, तो उनसे मिलने मैं भी वहाँ गई। मैंने बोला, “आप बहुत सुंदर बजा रहे थे, काश कि यह तार न टूटता और हम पूरी तरह राग को अंत तक सुन पाते।” इस पर अली अकबर भाई ने एक बड़ी मार््ममिक बात कही, जो आज तक मुझे भूलती नहीं। वे बोले— “बहन, जब बहुत सुर में तार लगता है, तो टूट जाता है।”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('151679c5-4133-4622-be4a-7e3d6a336fef', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उन््होंने अपने सुर को इतने पवित्र भाव से इतना डूबकर लगाया कि सरोद का तार टूट गया। इस प्रसंग से मुझे यह लगता है कि संगीत की सीमा इतनी अनंत है कि तार भी शुद्ध स््वर के आघात को सह नहीं पाता, टूटकर अलग हो जाता है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('186e1271-ade5-4131-a680-f3a204cc582c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आज जब उस््तताद अली अकबर खाँ या पंडित रविशंकर के संदर््भ में इन बातों को सोचती हूँ, तो इस बात पर विश््‍ववास करने का मन होता है कि हो सकता है मियाँ तानसेन से कोई ऐसा सच््चचा सुर जरूर लगा होगा कि बारिश हो गई या दीपक जल उठे!$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b82eb629-8ff3-4835-9164-48cc38ada863', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यतीींद्र मिश्र : दीदी, आप तो घर-घर में व्याप्‍त हैं। आपकी आवाज़ से लोगों की सुबह होती है। अगर मैं अतिरेक नहीं कर रहा, तो यह कहना वाजिब है कि आप अमर हैं और दूसरी लता मंगेशकर होना इस दुनिया में संभव नहीं है...$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('fba4154b-024d-43da-8e51-fb991ca4bce7', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लता मंगेशकर : मुझे भगवान ने बहुत कुछ दिया है। मुझे किसी बात की शिकायत नहीं है। मैं बहुत खुश हूँ। आप जैसे लोग अगर यह मानते हैं कि मैं अमर हूँ, तो यह मुझे मिलने वाले उस प्यार जैसा ही है, जो दुनिया ने मुझे दिया है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('89f8a98d-fc96-40e4-8628-2abd5038628b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरा गाना अमर है, पर शरीर तो अमर नहीं। उसे तो जाना ही है, आज नहीं तो कल। कल नहीं तो परसों या किसी न किसी दिन...। इस बात पर मुझे कोई अफसोस नहीं होता। वह तो होकर रहेगा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5edf7e4a-8a11-4ce5-af17-bd18b3e1a645', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमारे यहाँ यही कहा जाता है—‘गाव गेला वाहुन, नाव गेला राहुन’। मतलब गाँव तो बह जाता है, लेकिन जो नाम है, वह रह जाता है। मैं इसको हमेशा से मानती रही हूँ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('fa8cb45f-eee7-4bb1-b54b-315597072545', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक बात की मुझे सबसे ज्यादा खुशी है कि मैंने अपने पिताजी का नाम, थोड़ा ही सही मगर, आगे बढ़ाया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('fae9ba42-0756-4eef-b20b-9fd06552bbe7', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आज मुझे लगता है कि हे प्रभु! तुमने जो भी दिया, वह बहुत दिया, दूसरों से कहीं ज्यादा दिया। अपनी कृृपा की छाया से जैसे मुझे छाँह दी है, वैसे ही हर एक कलाकार और नेक इंसानों के ऊपर भी रखना... यही प्रार््थना है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL);





