  ('8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लता मंगेशकर ने अपने पिताजी का नाम आगे बढ़ाने को अपनी सबसे बड़ी खुशी क्यों बताया है? इस कथन के पीछे छिपी भावनाओं का विश्लेषण कीजिए।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लता मंगेशकर ने अपनी अंतिम प्रार्थना में प्रभु से क्या माँगा है और यह उनकी किस प्रकार की सोच को दर्शाता है?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
