  ('3f3f0bf9-ee94-497c-888d-58efd8a8de65', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यतीींद्र मिश्र : दीदी, आपके संगीत की अप्रतिम यात्रा पर बातचीत शुरू करते हैं... इस संवाद में मेरा प्रयास यह रहेगा कि मैं संगीत में आकंठ डूबे हुए आपके महान जीवन की उन दुर््लभ छवियों से उन करोड़ों प्रशंसकों को मिलवा सकूँ, जो आपको हर दिन सुनते हुए कहीं अपने जीवन को सार््थक ढंग से शुरू करने की प्रेरणा पाते हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
