  ('6203eb71-6a01-44a5-a8ca-cdc3ac839a37', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लता मंगेशकर : जी, जरूर। आपका बेहद शुक्रिया कि आपका ऐसा कुछ करने का मन है। आप पूछिए, मैं आपके प्रश्नों का जवाब देने के लिए तैयार हूँ। मैं कोशिश करूँगी कि जो कुछ भी मैंने संगीत में रहते हुए जाना है, उसे आपको बता सकूँ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6219c6b5-9331-4131-8a05-c5d4cfdda2af', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आपके माध््यम से ही मैं अपने करोड़ों प्रशंसकों का आभार व्यक्‍त करती हूँ, जो उन््होंने मुझे इतना प्रेम और सम््ममान दे रखा है। मुझे तो यह भी लगता है कि जितना प्रेम मुझे मिला है, शायद गाकर उतना आभार मैं अपने प्रशंसकों के प्रति जता नहीं पाई हूँ...$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('cfa2c1a2-30c0-4c39-8579-9a62b2649152', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यतीींद्र मिश्र : आपके पिताजी पं. दीनानाथ मंगेशकर की वे कौन-सी स््ममृतियाँ हैं, जो आज भी आपके स््मरण में जीवित हैं? जिनको याद करना आपको सुख से भरता है?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
