  ('48424b54-7794-41e6-9eff-c364bdec914c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मतलब वे कुछ कहते नहीं थे, न ही किसी बात पर डाँट पड़ती थी; मगर हम सभी समझ जाते थे कि हमको बुलाया किसलिए गया है। पिताजी उस समय पूछते थे, ‘समझ गए न?’ इस पर हम लोग कहते थे, ‘हाँ, हम लोग समझ गए।’$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3ced074c-2495-448e-b97f-0e16e7e15b1e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इसके बाद वे कहते थे कि ‘अच्छा अब जाओ, बाहर जाकर खेलो।’ इस तरह हमारे पिताजी का गुस्सा था, जो बिना कुछ कहे ही हम भाई-बहनों को डरा देता था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
