  ('f7749624-8644-44ad-9195-6d41bf9cde3c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यह मेरे पिताजी ने ही मुझे सिखाया था कि अगर कोई बात तुम्हें सही लगती है, तो उसे करो और किसी के$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0c8f19b2-3914-45de-8e2b-ded8a5ff172c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आगे झुकने की जरूरत नहीं है। इस तरह जब मैं याद करती हूँ, तो लगता है कि बाबा ऐसा कहते थे, बाबा ने यह कहा था, बाबा ने उस समय में इस तरह कोई निर््णय लिया था। यह सब मेरे बड़े काम आया है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('006ea9d6-212e-434a-8211-739a8144cca3', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमने हर तरह के दिन देखे थे। पिताजी की कंपनी जब अच्छी चलती थी, तो हम सब लोग बड़े शान से रहते थे। फिर पिताजी के निधन के बाद हमें यह भी देखना पड़ा कि बुरे हालात में कैसे जीना है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f44b064a-9523-49d8-b296-3b49c1b68ba2', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरी माँ का भी वही संस्कार था कि कैसे भी स््ववाभिमान के साथ जी लेना है, मगर किसी के आगे जाकर हाथ नहीं पसारना है।... और देखिए, ये सब बातें मेरे कितने काम आई हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4e22efcb-00ce-4bfd-8680-d7b5096b559c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आज मेरे पास पैसे हैं और नाम है। हम आज जहाँ रहते हैं, वह भले ही इतना छोटा-सा घर है, पर उसमें हम लोग बहुत खुश हैं। इस बात के लिए भी ईश्‍वर को धन््यवाद करते हैं कि बाबा ने जैसा सिखाया था, उस पर हम सभी भाई-बहनों ने चलने का प्रयास किया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7023b8a3-8c00-4ca5-88e4-ea9264c753a3', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यतीींद्र मिश्र : बचपन में आप सभी भाई-बहन फिल््में देखकर उसकी नकल उतारते थे। किसी खास फिल््म को देखकर उसकी नकल का स््मरण करेंगी? लता मंगेशकर : (हँसते हुए) अरे! यह तो हम सब भाई-बहन बहुत करते थे। फिल््में ही थीं, जो मनोरंजन का एक ऐसा माध््यम थीं जिनको देखकर बच््चचे अपने ढंग से कुछ-कुछ करते रहते थे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5c9eac00-5e19-415c-9207-9cceda22a5f5', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे याद है कि प्रभात फिल््म कंपनी की एक पिक््चर थी ‘संत तुकाराम’। फिल््म में दिखाया गया है कि तुकाराम सदेह बैकुंठ जाते हैं और उन््हें लेने ईश्‍वर का विमान आता है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b0df050e-f91f-4832-9b08-1d81889b4c6c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वे यह गीत गाते हुए स््वर््ग जाते हैं— ‘अमी जातो अमचा गावा, अमचा राम-राम ध््ययावा’ (मैं अपने गाँव जा रहा हूँ। सभी लोग मेरा राम-राम ले लीजिए)। हम कमरे में घर भर के गद्दे, तकिये एक के ऊपर एक रखकर ऊँचा स््वर््ग बनाते थे, जिस पर चढ़कर मैं बैठती थी और वहीं से यह गीत गाती थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('436b7126-856c-4359-85d8-87027577db1a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$नीचे कमरे में मीना, मेरे फूफा का बेटा पंढरीनाथ और आशा, ये तीनों तुकाराम के अनुयायी बनकर रोते थे और कहते थे— ‘हमें भी साथ ले लीजिए। हमें भी साथ ले चलिए।’ (खिलखिलाकर हँसती हैं) उस समय उषषा बहुत छोटी थी, इसलिए वह इन नाटकों में नहीं रहती थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b3de46fb-bd5e-44b3-b79d-3ebe5c973e44', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हम बहुत सारी फिल््मों की नकल उतारते थे, जिनमें धार््ममिक फिल््में ज्यादा होती थीं क््योंकि पिताजी धार््ममिक और देशभक््‍तति की फिल््मों के अलावा दूसरी फिल््में नहीं देखने देते थे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('dc1c5ca4-f654-439d-8294-7436b9ae944a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनका सख््त अनुशासन था और यह सब काम चोरी-चोरी तब होता था, जब पिताजी घर के बाहर हों और यह जान न पाएँ कि घर में फिल््मों का खेल खेला जा रहा है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f192a5c8-56d6-46b9-8301-e3b86c603343', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लता मंगेशकर : नहीं, मैंने शुरू में तो फिल््मों में काम ही किया था और कुल छह या सात फिल््मों में किया था। मैं बहुत छोटी थी उस समय, जब फिल््मों की दुनिया में अभिनय के मार्फ़त ही आई। मुझे कभी अच्छा नहीं लगा मेकअप करना, लाइट के सामने जाना और काफी लोग खड़े हैं, तो उनके सामने कभी रो रहे हैं और कभी हँस रहे हैं। गा भी रहे हैं। मुझे वह कभी अच्छा नहीं लगा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a52ea71a-714a-4ff8-a48b-59140c0fe563', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अच्छी फिल््मों को देखकर सराहने का जी जरूर करता है, मगर अभिनय करने के बारे में तो सोच भी नहीं सकती। एक फिल््म हमारे यहाँ हिंदी और मराठी दोनों में बनी थी ‘छत्रपति शिवाजी’। उसमें भालजी पेंढारकर थे जिन््हें मैं बाबा कहती थी। मैं उनके पास गई, हालाँकि उस वक्‍त तक मैंने अभिनय का काम छोड़ दिया था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a3ae6400-9796-4af9-95b3-33cd6340aada', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैंने उनसे खुद कहा—‘बाबा मैं चाहती हूँ कि इस फिल््म का आखिर का जो गाना है, उसमें दो लाइनें मैं भी आकर गाऊँ।’ तो फिर मैंने उसके हिंदी और मराठी, दोनों ही संस्करणों में बाद की दो पंक््‍ततियाँ गाई हैं, जिन दृश््यों में मैं मौजूद भी हूँ। मैं छत्रपति शिवाजी को बहुत पसंद करती हूँ, इसलिए बस इसी फिल््म के लिए मेरा मन हुआ कि भले ही एक दृश्य में सही, मगर यहाँ रहा जा सकता है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('698d0a5c-97e9-403b-ad72-b5a78e03ac64', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यतीींद्र मिश्र : उस दौर में आपके काम की परिस््थथितियाँ कैसी थीं? क्या वे आपके हिसाब से धीरे-धीरे अनुकूल होती गर्इं अथवा वैसे ही हमेशा की तरह एक चुनौती का सबब बनी रहीं, जैसे कि वे संघर््ष के दिनों में थीं? लता मंगेशकर : यह कह पाना मुश््ककिल होगा कि मेरी परिस््थथितियाँ कभी बहुत अच्छी या बुरी रही हों। मैं इन सब बातों पर ध्यान नहीं देती थी। अलबत्ता मैं उस जमाने से लेकर बाद तक बहुत मेहनत से अपने काम करती थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b37e7fcf-e3cf-40a0-9261-7a166b9966e5', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे याद है कि मेरी रेकॉर््डििंंग सुबह से रात तक चलती रहती थी। एक स््टूडियो से दूसरे और तीसरे स््टूडियो के चक्कर में ही पूरा दिन बीत जाता था। मुझे अपने गाने और रेकॉर््डििंंग के अलावा किसी दूसरी चीज की सुध नहीं रहती थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('75d8714e-a2f5-4fdb-a564-6902da007572', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमेशा यही बात दिमाग में घूमती थी कि किसी तरह बस मुझे अपने परिवार को देखना है। फिर वह रेकॉर््डििंंग का वक्‍त हो या घर का खाली समय। किस तरह मैं अपने परिवार के लिए ज्यादा से ज्यादा कमाकर उनकी जरूरतें पूरी कर सकती हूँ, इसी में सारा वक्‍त निकल जाता था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ef9e2f16-03b2-47f1-a184-abfb426893e5', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आप मेरी परिस््थथितियों के बारे में पूछ रहे हैं, तो सच बात तो यही है कि मुझे रेकॉर््डििंंग से या उसकी तकलीफों से इतना फर््क नहीं पड़ता था, जितना इस बात से कि आने वाले कल में मेरे कितने गीत रेकॉर््ड होने हैं। फलाँ फिल््म के खत््म होने के साथ मुझे नए कॉन्ट्ेक्ट की दूसरी नई फिल््मों के गाने कब रेकॉर््ड करने हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c298326f-9cfc-4c27-8d56-268c664bb862', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लता मंगेशकर : नहीं, मैंने शुरू में तो फिल््मों में काम ही किया था और कुल छह या सात फिल््मों में किया था। मैं बहुत छोटी थी उस समय, जब फिल््मों की दुनिया में अभिनय के मार्फ़त ही आई।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('948e0fec-9bd7-4aad-82d3-666bb560d68f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे कभी अच्छा नहीं लगा मेकअप करना, लाइट के सामने जाना और काफी लोग खड़े हैं, तो उनके सामने कभी रो रहे हैं और कभी हँस रहे हैं। गा भी रहे हैं। मुझे वह कभी अच्छा नहीं लगा। अच्छी फिल््मों को देखकर सराहने का जी जरूर करता है, मगर अभिनय करने के बारे में तो सोच भी नहीं सकती।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('233772f8-001f-429b-ab19-553e1fe03030', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे याद है कि मेरी रेकॉर््डििंंग सुबह से रात तक चलती रहती थी। एक स््टूडियो से दूसरे और तीसरे स््टूडियो के चक्कर में ही पूरा दिन बीत जाता था। मुझे अपने गाने और रेकॉर््डििंंग के अलावा किसी दूसरी चीज की सुध नहीं रहती थी। हमेशा यही बात दिमाग में घूमती थी कि किसी तरह बस मुझे अपने परिवार को देखना है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('fb0e6043-e3e7-42dd-986a-8757cdefac14', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरे पिताजी उस समय जीवित थे और जब वे अपने कार्यक्रमों के लिए तैयार होते थे, तो उनको जितने मेडल मिले थे, वे अपने कपड़ों पर सीने के बाईं तरफ लगाते थे। वह जमाना ऐसा था, जिसमें यह प्रचलन रहा कि कलाकार लोग अपने प्रदर्शनों में मिले हुए मेडल पहनकर ही बैठते थे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d8019fce-4345-4f83-84e1-f6ca58dd9e6d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे जगह तो याद नहीं है, मगर यह ठीक से याद है कि पिताजी के अलावा बाहर के किसी कलाकार को जो सबसे पहले मैंने गाते हुए सुना है, वह पंडित कुमार गंधर्व थे। कुमार गंधर्व जी जब काली शेरवानी पहनकर और अपने ढेर सारे मेडल लगाकर गाने के लिए बैठे, तो वह बात मुझे बहुत पसंद आई। मुझे तब हमेशा यह लगता था कि जब मैं बड़ी हो जाऊँगी, तब मुझे भी ऐसे ही मेडल मिलेंगे, जिसे लगाकर किसी कार्यक्रम में जाऊँगी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('923d920e-df8d-4bc5-8f1b-eac3e961d1b6', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अगर हम समय के चक्र (टाइम मशीन) को घुमाकर सन् 1949-50 में ले जाएँ, तो आपके फिल््मों से संबंधित सांगीतिक जीवन की शुरुआत में खेमचंद प्रकाश, शंकर-जयकिशन, हुस्नलाल-भगतराम जैसे म््यूजिक डायरेक्टर आते हैं और आपको एक मजबूत जमीन बनाने के लिए, ‘आएगा आने वाला’ (महल), ‘हवा में उड़ता जाए मोरा लाल दुपट्टा मलमल का’ (बरसात) और ‘चले जाना नहीं नैन मिला के’ (बड़ी बहन) जैसे गाने मिलते हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9bae75ce-2ad9-4ae8-badd-8a9db4381457', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इससे एक नए युग का सूत्रपात होता है, जो कहीं आपके कद को बड़ा बनाने में मददगार रहता है। मैं यह जानना चाहता हूँ कि यदि उस जमाने में ए.आर. रहमान आए होते, जतिन-ललित आए होते, शंकर-एहसान-लॉय होते, तो ये सारे गाने कैसे बनते? उस समय ‘आएगा आने वाला’ की आमद कैसी होती?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8ceacd04-a1b2-423c-96bb-7a3ee473453c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लता मंगेशकर : (हँसते हुए) बड़ा मजेदार प्रश्न है आपका। कहना मुश््ककिल है इस पर क्या बोलूँ? समझ में नहीं आ रहा है कि वाकई अगर ऐसा हुआ होता, तो ये गाने कैसे बनते। यह विचार और कल्पना तो सुनने में अच्छी लगती है, पर मैं पूरी तरह इसका आकलन नहीं कर सकती कि ‘आएगा आने वाला’ को ए.आर. रहमान ने बनाया होता या ‘हवा में उड़ता जाए’ को जतिन-ललित ने, तो कैसा प्रभाव पैदा होता।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5132d187-643a-4f57-ad39-82ba0870fed2', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मगर मैं इतना जरूर जानती हूँ कि कुछ बहुत बढ़़िया होता या बिल्कुल दूसरे अंदाज में सामने आता, जिसकी शायद धुनें और तर्ज़ भी अलग होते। मैं आपसे प्रश्न करती हूँ कि जो मेरे गाने रहमान ने बनाए या जतिन-ललित के लिए मैंने ‘मेरे ख््ववाबों में जो आए’ (दिलवाले दुल््हनिया ले जाएँगे) गाया है, उसे श््ययाम सुंदर जी, नौशाद साहब या अनिल विश््‍ववास ने रचा होता, तो आपके लिहाज से वह किस तरह$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c73184b9-d95a-4779-b143-4a930921fa69', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यतीींद्र मिश्र : अगर हम समय के चक्र (टाइम मशीन) को घुमाकर सन् 1949-50 में ले जाएँ, तो आपके फिल््मों से संबंधित सांगीतिक जीवन की शुरुआत में खेमचंद प्रकाश, शंकर-जयकिशन, हुस्नलाल-भगतराम जैसे म््यूजिक डायरेक्टर आते हैं और आपको एक मजबूत जमीन बनाने के लिए, ‘आएगा आने वाला’ (महल), ‘हवा में उड़ता जाए मोरा लाल दुपट्टा मलमल का’ (बरसात) और ‘चले जाना नहीं नैन मिला के’ (बड़ी बहन) जैसे गाने मिलते हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d14742b4-7444-45c1-b6ee-235baec61bd1', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे तब हमेशा यह लगता था कि जब मैं बड़ी हो जाऊँगी, तब मुझे भी ऐसे ही मेडल मिलेंगे, जिसे लगाकर किसी कार्यक्रम में जाऊँगी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('150ae46f-d1b7-4e3a-99fa-ed70637ca06a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यह विचार और कल्पना तो सुनने में अच्छी लगती है, पर मैं पूरी तरह इसका आकलन नहीं कर सकती कि ‘आएगा आने वाला’ को ए.आर. रहमान ने बनाया होता या ‘हवा में उड़ता जाए’ को जतिन-ललित ने, तो कैसा प्रभाव पैदा होता।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d9367288-6008-4569-ad55-348c7d8a411e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मगर मैं इतना जरूर जानती हूँ कि कुछ बहुत बढ़़िया होता या बिल्कुल दूसरे अंदाज में सामने आता, जिसकी शायद धुनें और तर्ज़ भी अलग होते।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3178d8b5-9fa9-4b93-86b4-b575ebf86706', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पुराने समयों में, जब मैंने ‘महल’, ‘बड़ी बहन’, ‘बरसात’, ‘तराना’, ‘बाजार’ और ‘संगदिल’ जैसी फिल््मों के लिए पाश्‍ र््वगायन किया था, उस समय तकनीकी रूप से सिनेमा में बहुत तरक्की नहीं हुई थी। ‘आएगा आने वाला’ में मुझे हाॅल में बहुत दूर से चलकर दबे पाँव रेकॉर््डििंंग वाले माईक तक आना पड़ता था और उसी अनुपात में रेकॉर््डििंंग के माईक पर स््वर का उतार-चढ़़ाव कैद किया जाता था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('eb01fbd6-b8ad-4f67-895c-b6f8582d7b24', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बहुत सारे ऐसे गाने मुझे याद हैं जिसमें कुछ विशेषष प्रभावों को देने के लिए अनिल विश््‍ववास, श््ययाम सुंदर, सज्जाद हुसैन, सलिल चौधरी और सी. रामचंद्र ने कुछ नए तरीके और अजीबोगरीब टोटके आजमाए थे, जिनसे गीतों में वह प्रभाव पैदा हो सका। आज, जो स््थथिति है और जिस तरह हमारी तकनीक विकसित हो चुकी है, उसमें अगर इन लोगों को काम करने का मौका मिलता, तब तो कमाल ही हो गया होता। न जाने कितना और अधिक एडवांस किस््म का ये लोग संगीत रच पाते, आप सोच सकते हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('91e4198e-ba6f-4f93-b3f2-dba75745dbb5', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ठीक उसी तरह, जैसा सुंदर और स््तरीय संगीत आज के संगीतकार बना रहे हैं— रहमान, जतिन-ललित और तमाम अन्य लोग— अगर पीछे जाकर काम करते, तो कितनी मुश््ककिलें आतीीं और कितना संघर््ष करते हुए वे सब अपना गाना बनाते, इसका अंदाजा भी लगाया जा सकता है। मेरे लिए भी यह कम चुनौती की बात नहीं कि मैं अनिल विश््‍ववास की धुनों जैसा काम रहमान के साथ कर रही होती और उसी तरह इन नए लोगों की धुनों पर नौशाद साहब के लिए रेकॉर््ड करती, तो कैसा होता?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3cc12ec3-8912-4763-a9e6-4a52b731e62a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यतीींद्र मिश्र : इसी समय विषषय परिवर््तन करते हुए आपसे कुछ व््यक््‍ततिगत सवाल पूछने का मन हो रहा है। इस संदर््भ में आपके व््यक््‍ततित््व को देखते हुए यह बात दिमाग में आती है कि आपने रंगों से हमेशा परहेज किया है। विशेषषकर अपने पहनावे में भी इस बात का ध्यान रखा$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7a62feab-2611-47ed-affe-fa811f540f96', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यह वाकई बहुत रोचक और सोचने वाली बात है कि समय के हेर-फेर से हमारे गीतों का स््वभाव कैसा होता? इतना जरूर मैं कहना चाहूँगी कि पुराने समयों में, जब मैंने ‘महल’, ‘बड़ी बहन’, ‘बरसात’, ‘तराना’, ‘बाजार’ और ‘संगदिल’ जैसी फिल््मों के लिए पाश्‍ र््वगायन किया था, उस समय तकनीकी रूप से सिनेमा में बहुत तरक्की नहीं हुई थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f4263f9c-0e38-42b4-9289-e1b7851d7bd8', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$‘आएगा आने वाला’ में मुझे हाॅल में बहुत दूर से चलकर दबे पाँव रेकॉर््डििंंग वाले माईक तक आना पड़ता था और उसी अनुपात में रेकॉर््डििंंग के माईक पर स््वर का उतार-चढ़़ाव कैद किया जाता था। बहुत सारे ऐसे गाने मुझे याद हैं जिसमें कुछ विशेषष प्रभावों को देने के लिए अनिल विश््‍ववास, श््ययाम सुंदर, सज्जाद हुसैन, सलिल चौधरी और सी. रामचंद्र ने कुछ नए तरीके और अजीबोगरीब टोटके आजमाए थे, जिनसे गीतों में वह प्रभाव पैदा हो सका।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('36f4da7d-ea4f-49f6-bfe6-4c20b48f25aa', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आज, जो स््थथिति है और जिस तरह हमारी तकनीक विकसित हो चुकी है, उसमें अगर इन लोगों को काम करने का मौका मिलता, तब तो कमाल ही हो गया होता। न जाने कितना और अधिक एडवांस किस््म का ये लोग संगीत रच पाते, आप सोच सकते हैं। ठीक उसी तरह, जैसा सुंदर और स््तरीय संगीत आज के संगीतकार बना रहे हैं— रहमान, जतिन-ललित और तमाम अन्य लोग— अगर पीछे जाकर काम करते, तो कितनी मुश््ककिलें आतीीं और कितना संघर््ष करते हुए वे सब अपना गाना बनाते, इसका अंदाजा भी लगाया जा सकता है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7ec8510a-544e-41f8-81d9-d92895817fbe', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरे लिए भी यह कम चुनौती की बात नहीं कि मैं अनिल विश््‍ववास की धुनों जैसा काम रहमान के साथ कर रही होती और उसी तरह इन नए लोगों की धुनों पर नौशाद साहब के लिए रेकॉर््ड करती, तो कैसा होता? यतीींद्र मिश्र : इसी समय विषषय परिवर््तन करते हुए आपसे कुछ व््यक््‍ततिगत सवाल पूछने का मन हो रहा है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('309963b0-0d8e-4f19-9c1a-ff20af1863b7', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यह वाकई बहुत रोचक और सोचने वाली बात है कि समय के हेर-फेर से हमारे गीतों का स््वभाव कैसा होता? इतना जरूर मैं कहना चाहूँगी कि पुराने समयों में, जब मैंने ‘महल’, ‘बड़ी बहन’, ‘बरसात’, ‘तराना’, ‘बाजार’ और ‘संगदिल’ जैसी फिल््मों के लिए पाश्‍ र््वगायन किया था, उस समय तकनीकी रूप से सिनेमा में बहुत तरक्की नहीं हुई थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1fd57f46-9910-42e0-bae0-38a0625448c5', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बहुत सारे ऐसे गाने मुझे याद हैं जिसमें कुछ विशेषष प्रभावों को देने के लिए अनिल विश््‍ववास, श््ययाम सुंदर, सज्जाद हुसैन, सलिल चौधरी और सी. रामचंद्र ने कुछ नए तरीके और अजीबोगरीब टोटके आजमाए थे, जिनसे गीतों में वह प्रभाव पैदा हो सका। आज, जो स््थथिति है और जिस तरह हमारी तकनीक विकसित हो चुकी है, उसमें अगर इन लोगों को काम करने का मौका मिलता, तब तो कमाल ही हो गया होता।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('56cf6a5a-ec93-4c7f-a2ca-4265ba210003', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गंगा...तो यह त्योहार हम राम आगमन मानकर मनाते हैं, जबकि बाकी जगहों पर दुर््गगा की आराधना में नवरात्र होता है। महाराष्‍ट्र में उस तरह नवरात्र नहीं मनता, जिस तरह गुजरात, उत्तर प्रदेश और राजस्थान में दुर््गगा की आराधना में यह त्योहार मनाया जाता है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e78a44b3-b583-49f4-9cf2-961a1a1238cf', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यतीींद्र मिश्र : त्योहारों की ऐसी कोई खास बात, जो आपके शुरुआती जीवन में परंपरा की तरह निभती रही हो और जिसे आपने बाद में भी पूरी आत््ममीयता के साथ निभाना जारी रखा। लता मंगेशकर : ऐसी कोई खास बात मुझे याद नहीं आती। अलबत्ता इतना जरूर कहूँगी कि पचास का दशक रहा होगा, जब मैं फिल््म इंडस्ट्ी में नई-नई आई थी और मेरा काम कुछ चल निकलना शुरू हुआ था। उस दौरान मैंने कुछ सालों तक दीवाली के दिन अपने सीनियर म््यूजिक डायरेक््टर््स के यहाँ मिठाई लेकर जाने का चलन शुरू किया था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0a56d1ac-9e7c-4780-9c29-f0d3fb031e4d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक बार बड़ा मजेदार वाकया हुआ कि मैं नौशाद साहब के घर सुबह करीब साढ़े पाँच बजे पहुँच गई और जब कॉलबेल बजाया, तो उनींदे से नौशाद साहब मुझे गेट पर खड़ा देखकर डर गए। वे डरकर पूछने लगे— “लता बाई सब खैरियत तो है, इतने सबेरे क्या मुसीबत आन पड़ी?”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d9c5b4ed-d415-4910-8cc3-bf373b47aa40', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैंने उन््हें हँसकर कहा, “कुछ नहीं नौशाद साहब, आज दीवाली है तो आपको बधाई देने और मिठाई पहुँचाने चली आई।” इस पर वे बोले, “अरे इतनी सुबह क््यों परेशान हुई?” तब मैंने उनको हँसते हुए जवाब दिया कि नौशाद साहब आपके अलावा मुझे अभी दो-तीन जगह— अनिल विश््‍ववास जी, रोशनलाल, मदन भैया और बर््मन दादा के यहाँ भी जाना है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2639ff55-6d0f-467e-8810-c074a254a3c4', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इस पर वे लाड़ से भरकर बोले— “हाँ। मैं बिल्कुल भूल गया! लेकिन पहले बैठो, चाय पियो और मुँह मीठा करो, फिर जाने देंगे। फिर बोले, “लता, तुम हम सबको मिठाई बाँट रही हो, लेकिन हम सारे संगीतकारों को मिलकर तो तुम््हें मिठाई खिलानी चाहिए, जो तुमने हमारी धुनों में इतनी मिठास घोली है।” नौशाद साहब से मैंने यही इतना भर कहा कि आप आशीर््ववाद दीजिए कि आगे भी जीवन में हर दीवाली के साथ मैं और मधुर से मधुर गीत गा सकूँ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('401ef7cc-8421-434e-9e85-7aba0465e371', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यतीींद्र मिश्र : त्योहारों के संदर््भ में एक बात और ध्यान में आती है कि अधिकांश प्रदेशों में पर्वों व अनुष््‍ठठानों से संदर््भित घर-घर गीत गाए जाने का प्रचलन रहा है। उदाहरण के लिए होली के मौके पर फाग और धमार, बिहार में छठ पूजा पर छठ के गीत, जन््ममाष्‍टमी और रामनवमी में ईश्‍वर के जन््म के कारण सोहर और बधावा आदि गाने का मामला।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e287dac0-3d51-444f-b48e-340217147bb8', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ये गीत ज्यादातर घर और मोहल्ले की स्‍‍त्रर‍ियाँ ही गाती हैं, गायन एक रिवाज की तरह कायम है। ऐसे में महाराष्‍ट्र के संदर््भ में आपके देखे ऐसे कौन-से अवसर आए हैं?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('238e1851-6c41-4b1c-bdf1-42368cb1a19f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पचास का दशक रहा होगा, जब मैं फिल््म इंडस्ट्ी में नई-नई आई थी और मेरा काम कुछ चल निकलना शुरू हुआ था। उस दौरान मैंने कुछ सालों तक दीवाली के दिन अपने सीनियर म््यूजिक डायरेक््टर््स के यहाँ मिठाई लेकर जाने का चलन शुरू किया था। आप सुनकर हैरान होंगे कि मैं ऐन दीवाली के दिन तड़के पाँच बजे ही नहा-धोकर बहुत सारे संगीतकारों के घर मिठाई लेकर पहुँच जाती थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f0bc0b2e-fb43-440f-848b-e61467ddc46b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$फिर बोले, “लता, तुम हम सबको मिठाई बाँट रही हो, लेकिन हम सारे संगीतकारों को मिलकर तो तुम््हें मिठाई खिलानी चाहिए, जो तुमने हमारी धुनों में इतनी मिठास घोली है।”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3658310f-a357-4e76-b19d-21bfcae29ee2', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गंगा...तो यह त्योहार हम राम आगमन मानकर मनाते हैं, जबकि बाकी जगहों पर दुर््गगा की आराधना में नवरात्र होता है। महाराष्‍ट्र में उस तरह नवरात्र नहीं मनता, जिस तरह गुजरात, उत्तर प्रदेश और राजस्थान में दुर््गगा की आराधना में यह त्योहार मनाया जाता है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f07a001c-43d6-4058-9dfe-d3feac9cf693', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमारे यहाँ होली और दीवाली पर तो इस तरह घरों में गीत नहीं होता। यह जरूर है कि विवाह के बाद जब नई बहू घर में आती है, तब एक पूजा होती है घरों में, जिसमें पास-पड़ोस की बहुत सारी औरतें आती हैं। यह मंगलागौर कहलाता है। सारी औरतें बिल्कुल मुग्ध भाव से गीत गाती हैं और नाचती भी हैं। बिल्कुल ठेठ गँवई अंदाज में यह मंगलागौर का उत््सव मनाया जाता है, मगर आहिस््तता-आहिस््तता वह भी अब खत््म हो रहा है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('842ba6d1-fe21-46dc-ac37-badcfe7e039f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे अच्छी तरह से याद है; जब मैं बहुत छोटी थी, तब घर-परिवार या पड़ोस में किसी की भी शादी के बाद यह मंगलागौर मनाया जाता था और हम सभी लोग उसमें खूब नाचते-गाते थे। उनमें स्‍‍त्रर‍ियाँ नौटंकी और तमाशा की तरह भी कुछ-कुछ करती थीं। मतलब कोई कुछ भी रूप धरकर नाचता था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4818485b-dae6-43ef-b2a8-cb53efb655a6', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यतीींद्र मिश्र : दीदी, कोरस में गाने वाली लड़कियोों के साथ आपके कैसे रिश््तते रहे? क्या वे सब भी आप लोगों की गायिकी में कोई सहयोग करती थीं या उनका एक अलग ही विभाग होता था, जो मुख्य पाश्‍ र््वगायक-गायिकाओं से अलग रहता था?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b6bf9e93-a257-4407-96af-b5e10e806c76', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उस वक्‍त एक ऐसा ग्रुप था, जो सब जगह जाता था। नौशाद साहब के यहाँ, मदन मोहन जी के यहाँ। शंकर-जयकिशन, एस.डी. बर््मन, आर.डी. बर््मन, लक्ष्मीकांत-प्यारेलाल— ये जितने भी लोग थे; सभी के यहाँ एक ही ग्रुप की लड़कियाँ थीं, जो कोरस में गाने जाती थीं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f0e7a731-4aa4-4684-b1a3-096ad92717bb', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इसलिए सबसे मेल-मुलाकात भी गहरी पहचान में बदल गई थी। मेरा कोरस की लड़कियों के साथ बहुत अच्छा संबंध था। मतलब जितनी भी लड़कियाँ थीं, वो बिल्कुल मेरे घर जैसी थीं। सबका ही घर में आना-जाना होता था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('072d1889-9d07-4204-9aa0-c7dcd5e05f5a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मीना की शादी जब कोल्हापुर में हुई, तो कोरस की सारी लड़कियाँ और लड़के वहाँ आए थे और उन लोगों ने वहाँ खूब गाने गाए और डांस किया था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0e5fb723-10cb-48d9-8dae-d730df7f1f87', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जहाँ तक मुझे याद पड़ता है, सन् 1960 में जो ग्रुप कोरस गाने वालों का हमें मिला था, वह लगभग अस्सी तक वैसे ही चला है। 1980 के पास जाकर वह बदला गया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('84274511-f986-4257-a89e-0b1a0b2248dc', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$फिर अस्सी के बाद तो यह भी हो गया था कि कोरस वालों का म््यूजिक पहले रेकॉर््ड हो जाता था। बाद में हम लोग जाकर अपने गाने गा आते थे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7171a00e-af3f-4794-923d-22ff46db789a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उससे पहले के दौर में पुरुषष और स्‍‍त््री्री आवाज़ों के कोरस हम लोगों के गीतों के साथ ही रेकॉर््ड होते थे। भले ही वह गाना डुएट हो या फिर कोई सोलो सांग। अकसर मुकेश भैया और मेरे गाने या किशोर कुमार और मेरे गानों में कोरस की लड़कियाँ साथ ही गाती थीं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('566668ed-7a9c-4cfe-81d3-edd4ee6d1fde', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनमें से कुछ के नाम तो मुझे अभी भी याद हैं। कुछ एक लड़कियाँ बहुत सुरीला गाती थीं, जिनमें कविता, गांधारी, कल्याणी, सुमन और रेखा थीं। यह सब मुझे बड़ी भली और अच्छी लगती थीं। कविता और गांधारी बहनें थीं और$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('cdea23cb-d376-453a-ac31-297dcb56224b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दोनों साथ ही कोरस में गाती थीं। रेखा शादी-शुदा बाल-बच््चों वाली औरत थी, जो अच्छी तरीके से कोरस में साथ देती थी। कल्याणी की भी आवाज़ सुंदर थी। यह सब इतनी भली थीं कि जब रेकॉर््डििंंग के लिए आती थीं, तो अकसर वहाँ स््टूडियो में ज्यादा कुर््ससियाँ नहीं होती थीं। वे सब बड़े मजे से जमीन पर बैठती थीं और अकसर मैं भी रेकॉर््डििंंग में आकर वहीं जमीन पर बैठकर उन सभी के साथ बातें करती थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a5725268-ea92-4db2-afdf-0f00b24ccc0e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यह मैं उन कोरस गाने वाली लड़कियोों की बात कर रही हूँ, जो बहुत शुरुआती दौर में लगभग पचास और साठ के दशक में संगीतकारों के यहाँ कोरस गाने के लिए जाती रही हैं। आजकल का मुझे कुछ मालूम नहीं है। अब कौन-कौन से लोग हैं और उनका सिंगर््स के साथ में गाना रेकॉर््ड होता है या अलग से? यह मुझे मालूम नहीं है। मुझसे मिलने वाले जितने लड़के और लड़कियाँ थीं, उन सबने बहुत बाद तक संपर््क बनाया हुआ था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('13bc7bba-cadf-4316-96c0-61caa8770442', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यतीींद्र मिश्र : संगीत की प्राचीन परंपरा में बहुत सारी जनश्रुतियाँ और कहानियाँ संगीत को गरिमा और शिखर देने के संदर््भ में कही जाती रही हैं या हम इस तरह कह सकते हैं कि परंपरा में व्याप्‍त रही हैं। मसलन स््ववामी हरिदास और तानसेन के युग की बहुत सारी कथाओं में यह मान््यताएँ भी प्रचलित रहीं कि तानसेन के दीपक राग गाने से दीये जल उठे या कि उनकी पुत्रियों ताना-रीरी के मेघ राग गाने से वर््षषा होने लगी। इस तरह की अवधारणाओं पर आप किस तरह सोचती हैं?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('bd551266-daf2-42be-8570-fb3fef1a84b3', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लता मंगेशकर : यह जिस जमाने की कथाएँ हैं, जिसमें हरिदास बाबा और तानसेन जैसे महान संगीतकारों के लिए ऐसा कहा गया, तो हो सकता है कि उनकी कला में कोई सच््चचा सुर या आत््ममा की आवाज़ लगी होगी, तो ऐसा कुछ घट गया होगा, ऐसा हम आदर में मान लेते हैं। परंतु यह निश्‍च‍ित ही हुआ होगा, यह कम से कम मैं नहीं कह सकती क््योंकि ऐसा मेरा कोई अनुभव नहीं है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e3e9b4df-ce5b-4926-b1cb-f2c6d1b88535', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हालाँकि मैं यह मानती हूँ कि संगीत में वह असीम शक््‍तति है कि कुछ अप्रत््ययाशित वह जरूर रच देता है, जिसका अनुभव भी कई बार हमें हुआ है। कई बार अपने बाबा पंडित दीनानाथ मंगेशकर को सुनते हुए भी मैं कुछ अप्रत््ययाशित अनुभव करती थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ace062c3-42ab-4d80-992e-218b7b522b6a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दोनों साथ ही कोरस में गाती थीं। रेखा शादी-शुदा बाल-बच््चों वाली औरत थी, जो अच्छी तरीके से कोरस में साथ देती थी। कल्याणी की भी आवाज़ सुंदर थी। यह सब इतनी भली थीं कि जब रेकॉर््डििंंग के लिए आती थीं, तो अकसर वहाँ स््टूडियो में ज्यादा कुर््ससियाँ नहीं होती थीं। वे सब बड़े मजे से जमीन पर बैठती थीं और अकसर मैं भी रेकॉर््डििंंग में आकर वहीं जमीन पर बैठकर उन सभी के साथ बातें करती थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('14c6fff4-c1c0-4d4c-98bd-2f1ffbd84c6e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यतीींद्र मिश्र : संगीत की प्राचीन परंपरा में बहुत सारी जनश्रुतियाँ और कहानियाँ संगीत को गरिमा और शिखर देने के संदर््भ में कही जाती रही हैं या हम इस तरह कह सकते हैं कि परंपरा में व्याप्‍त रही हैं। मसलन स््ववामी हरिदास और तानसेन के युग की बहुत सारी कथाओं में यह मान््यताएँ भी प्रचलित रहीं कि तानसेन के दीपक राग गाने से दीये जल उठे या कि उनकी पुत्रियों ताना-रीरी के मेघ राग गाने से वर््षषा होने लगी। इस तरह की अवधारणाओं पर आप किस तरह सोचती हैं?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d72724f4-9421-4683-b845-34d44271f0bc', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लता मंगेशकर : यह जिस जमाने की कथाएँ हैं, जिसमें हरिदास बाबा और तानसेन जैसे महान संगीतकारों के लिए ऐसा कहा गया, तो हो सकता है कि उनकी कला में कोई सच््चचा सुर या आत््ममा की आवाज़ लगी होगी, तो ऐसा कुछ घट गया होगा, ऐसा हम आदर में मान लेते हैं। परंतु यह निश्‍च‍ित ही हुआ होगा, यह कम से कम मैं नहीं कह सकती क््योंकि ऐसा मेरा कोई अनुभव नहीं है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('62663fd7-9fe1-45c8-8fb7-fa3ce7982e5e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हालाँकि मैं यह मानती हूँ कि संगीत में वह असीम शक््‍तति है कि कुछ अप्रत््ययाशित वह जरूर रच देता है, जिसका अनुभव भी कई बार हमें हुआ है। कई बार अपने बाबा पंडित दीनानाथ मंगेशकर को सुनते हुए भी मैं कुछ अप्रत््ययाशित अनुभव करती थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('360575c9-b456-4f4d-a1ad-fd609a450bb1', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यह मैं उन कोरस गाने वाली लड़कियोों की बात कर रही हूँ, जो बहुत शुरुआती दौर में लगभग पचास और साठ के दशक में संगीतकारों के यहाँ कोरस गाने के लिए जाती रही हैं। आजकल का मुझे कुछ मालूम नहीं है। अब कौन-कौन से लोग हैं और उनका सिंगर््स के साथ में गाना रेकॉर््ड होता है या अलग से? यह मुझे मालूम नहीं है। मुझसे मिलने वाले जितने लड़के और लड़कियाँ थीं, उन सबने बहुत बाद तक संपर््क बनाया हुआ था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4c50a9bc-0483-4cbc-ad01-469e25006a83', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आपको एक वाकया बताती हूँ। मैं मुंबई में उस््तताद अली अकबर खाँ और पंडित रविशंकर का एक कंसर््ट सुन रही थी। मैं श्रोताओं की पंक््‍तति में बिल्कुल आगे बैठी अली अकबर भाई का वादन सुन रही थी और वे अत््यंत मंत्रमुग्ध किस््म का वादन कर रहे थे। तभी कुछ समय बीता होगा, मसलन पचास-साठ मिनट कि ‘ठन’ से उनके सरोद का एक तार टूटा और उन््हें बजाना बंद करना पड़ा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('246887bb-5299-4c0e-9b28-fb1fcf8b51d9', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जब वे उठकर पीछे ग्रीन रूम में गए, तो उनसे मिलने मैं भी वहाँ गई। मैंने बोला, “आप बहुत सुंदर बजा रहे थे, काश कि यह तार न टूटता और हम पूरी तरह राग को अंत तक सुन पाते।” इस पर अली अकबर भाई ने एक बड़ी मार््ममिक बात कही, जो आज तक मुझे भूलती नहीं। वे बोले— “बहन, जब बहुत सुर में तार लगता है, तो टूट जाता है।”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e6676ebe-05ff-4ffb-b3da-38bd011a13c2', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उन््होंने अपने सुर को इतने पवित्र भाव से इतना डूबकर लगाया कि सरोद का तार टूट गया। इस प्रसंग से मुझे यह लगता है कि संगीत की सीमा इतनी अनंत है कि तार भी शुद्ध स््वर के आघात को सह नहीं पाता, टूटकर अलग हो जाता है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('08857faf-022d-4c90-ac31-066e52df05a4', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आज जब उस््तताद अली अकबर खाँ या पंडित रविशंकर के संदर््भ में इन बातों को सोचती हूँ, तो इस बात पर विश््‍ववास करने का मन होता है कि हो सकता है मियाँ तानसेन से कोई ऐसा सच््चचा सुर जरूर लगा होगा कि बारिश हो गई या दीपक जल उठे!$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('69f43786-e7e0-4306-b693-88a5d0d47a89', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यतीींद्र मिश्र : दीदी, आप तो घर-घर में व्याप्‍त हैं। आपकी आवाज़ से लोगों की सुबह होती है। अगर मैं अतिरेक नहीं कर रहा, तो यह कहना वाजिब है कि आप अमर हैं और दूसरी लता मंगेशकर होना इस दुनिया में संभव नहीं है...$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('464e8b5c-c860-4e27-a73f-5fdd1b9a600c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लता मंगेशकर : मुझे भगवान ने बहुत कुछ दिया है। मुझे किसी बात की शिकायत नहीं है। मैं बहुत खुश हूँ। आप जैसे लोग अगर यह मानते हैं कि मैं अमर हूँ, तो यह मुझे मिलने वाले उस प्यार जैसा ही है, जो दुनिया ने मुझे दिया है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1b3575e2-c9be-4bc9-93b1-a735d5339fe5', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरा गाना अमर है, पर शरीर तो अमर नहीं। उसे तो जाना ही है, आज नहीं तो कल। कल नहीं तो परसों या किसी न किसी दिन...। इस बात पर मुझे कोई अफसोस नहीं होता। वह तो होकर रहेगा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8c0c4817-f194-4d22-a264-933d1de5fa6a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमारे यहाँ यही कहा जाता है—‘गाव गेला वाहुन, नाव गेला राहुन’। मतलब गाँव तो बह जाता है, लेकिन जो नाम है, वह रह जाता है। मैं इसको हमेशा से मानती रही हूँ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a354da04-5ff3-4994-a63c-11fed58671a0', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक बात की मुझे सबसे ज्यादा खुशी है कि मैंने अपने पिताजी का नाम, थोड़ा ही सही मगर, आगे बढ़ाया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('cdb142a3-1c19-4033-be70-b8449b8b9492', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आज मुझे लगता है कि हे प्रभु! तुमने जो भी दिया, वह बहुत दिया, दूसरों से कहीं ज्यादा दिया। अपनी कृृपा की छाया से जैसे मुझे छाँह दी है, वैसे ही हर एक कलाकार और नेक इंसानों के ऊपर भी रखना... यही प्रार््थना है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4adf5223-7904-4dd9-8c57-81f6928ef629', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यतीींद्र मिश्र : दीदी, आपके संगीत की अप्रतिम यात्रा पर बातचीत शुरू करते हैं... इस संवाद में मेरा प्रयास यह रहेगा कि मैं संगीत में आकंठ डूबे हुए आपके महान जीवन की उन दुर््लभ छवियों से उन करोड़ों प्रशंसकों को मिलवा सकूँ, जो आपको हर दिन सुनते हुए कहीं अपने जीवन को सार््थक ढंग से शुरू करने की प्रेरणा पाते हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('29357d26-9059-419c-bda6-046af1b64044', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आप अगर तैयार हों, तो मैं ऐसे असंख्य शुभचिंतकोों, आपके संगीत के प्रति दीवानगी की हद तक समर््पित श्रोताओं और फिल््म-संगीत के प्रति आदर का भाव रखने वाले तमाम देशवासियों की ओर से प्रणाम करते हुए आपसे प्रश्न पूछना चाहूँगा...$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('46556323-a147-4a2c-bb62-8154ef1cb5ca', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लता मंगेशकर : जी, जरूर। आपका बेहद शुक्रिया कि आपका ऐसा कुछ करने का मन है। आप पूछिए, मैं आपके प्रश्नों का जवाब देने के लिए तैयार हूँ। मैं कोशिश करूँगी कि जो कुछ भी मैंने संगीत में रहते हुए जाना है, उसे आपको बता सकूँ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c155cd28-da24-45a0-89ac-29ba5516d952', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आपके माध््यम से ही मैं अपने करोड़ों प्रशंसकों का आभार व्यक्‍त करती हूँ, जो उन््होंने मुझे इतना प्रेम और सम््ममान दे रखा है। मुझे तो यह भी लगता है कि जितना प्रेम मुझे मिला है, शायद गाकर उतना आभार मैं अपने प्रशंसकों के प्रति जता नहीं पाई हूँ...$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9fe05230-8491-4386-a085-b9ee3f033870', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यतीींद्र मिश्र : आपके पिताजी पं. दीनानाथ मंगेशकर की वे कौन-सी स््ममृतियाँ हैं, जो आज भी आपके स््मरण में जीवित हैं? जिनको याद करना आपको सुख से भरता है?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('425e284a-483a-4828-82df-8a17b7e0d0aa', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लता मंगेशकर : कई बातें हैं। जैसे हम लोग बचपन में जब बहुत शरारत करते थे, तब पिताजी सबको बुलाकर अपने सामने खड़ा करते थे। वे बस हमको गंभीरता से देखते थे और इतने में ही हमारा रोना शुरू हो जाता था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1bced836-ec56-4213-b175-789ce69888ca', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मतलब वे कुछ कहते नहीं थे, न ही किसी बात पर डाँट पड़ती थी; मगर हम सभी समझ जाते थे कि हमको बुलाया किसलिए गया है। पिताजी उस समय पूछते थे, ‘समझ गए न?’ इस पर हम लोग कहते थे, ‘हाँ, हम लोग समझ गए।’$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('393c9d75-bc53-4846-9f35-9411d7ea32cf', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इसके बाद वे कहते थे कि ‘अच्छा अब जाओ, बाहर जाकर खेलो।’ इस तरह हमारे पिताजी का गुस्सा था, जो बिना कुछ कहे ही हम भाई-बहनों को डरा देता था। मेरे पिताजी कमाल के आदमी थे, जिन््हें मैंने हमेशा अपने काम और संगीत में डूबा हुआ ही देखा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('28a90b17-c28a-43b5-a89f-54c42eec4a51', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनकी ड्रामा कंपनी के नाटक रात नौ बजे शुरू होते थे और देर रात दो से तीन बजे तक जाकर समाप्‍त होते थे। इतनी देर एक नाटक में समय इसलिए लगता था कि ऐसी भी बातें होती हैं ऐसी भी बातें होती हैं (लता मंगेशकर से साक्ात्कार)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('90fd64c3-4334-46ca-9635-521a0d87aede', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यतीींद्र मिश्र : दीदी, आपके संगीत की अप्रतिम यात्रा पर बातचीत शुरू करते हैं... इस संवाद में मेरा प्रयास यह रहेगा कि मैं संगीत में आकंठ डूबे हुए आपके महान जीवन की उन दुर््लभ छवियों से उन करोड़ों प्रशंसकों को मिलवा सकूँ, जो आपको हर दिन सुनते हुए कहीं अपने जीवन को सार््थक ढंग से शुरू करने की प्रेरणा पाते हैं। आप अगर तैयार हों, तो मैं ऐसे असंख्य शुभचिंतकोों, आपके संगीत के प्रति दीवानगी की हद तक समर््पित श्रोताओं और फिल््म-संगीत के प्रति आदर का भाव रखने वाले तमाम देशवासियों की ओर से प्रणाम करते हुए आपसे प्रश्न पूछना चाहूँगा...$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('aa0b3cb0-10ef-4fcd-949c-6f9ac65136c8', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक नाटक के पाँच अंक होते थे। फिर उसमें लंबी-लंबी रागदारी वाले गायन की भी परंपरा थी। एक बार पिताजी जब गाना शुरू करते थे, तो खूब सीटियाँ, तालियाँ और ‘वन्स मोर’ मिलता था। बाबा माइक पर थोड़ी तेज आवाज़ में गाते थे, जो सुनने पर बहुत अच्छा लगता था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c880c43a-327c-46ae-9134-820dc7c97377', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरे पिताजी की एक बड़ी विशेषता यह भी थी कि वे एक राग को गाते हुए उसमें सुर बदलकर भी अपना गायन करते थे। मतलब एक राग गाते समय किसी भी सुर को ‘सा’ (षषडज) बनाकर इस तरह राग को बदल देते थे कि वह कुछ नया हो जाता था और फिर उसी समय नए राग में गाते हुए दोबारा से पहले राग और उसके सुर में वापस लौट आते थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('beed704a-1c78-4921-a7df-eefecad58092', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उस समय म्यूजिकल ड्रामा का बहुत चलन था। हमारे यहाँ कभी भी बिना म्यूज़िक के कोई ड्रामा हुआ ही नहीं। एक नई बात मेरे पिताजी के नाटकों में यह भी थी कि वे पहली बार मराठी रंगमंच में कर्नाटक और पंजाब का संगीत लेकर आए। मतलब उन्होंने बाकायदा कर्नाटक जाकर वहाँ का कुछ गीत और संगीत सीखा था, जिसे अपने नाटकों में डाला।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('01c47a38-c509-464b-a15d-62267d0dc88c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे यह भी याद है कि जिस दिन कोई ड्रामा नहीं होता था, उस दिन घर में संगीत की सभा होती थी और बहुत सारे लोग हमारे घर आते थे। फिर वे उसमें नाटक का कोई गीत नहीं गाते थे, बल्कि उस दिन सिर्फ शास्त्रीय संगीत होता था। मेरे पिताजी के गाए हुए शास्त्रीय संगीत के कई रिकॉर्ड एच.एम.वी. से रिलीज हुए हैं और जहाँ तक मुझे याद पड़ता है कि एक रिकॉर्ड उन्होंने राग जयजयवंती का भी बनाया था, जिसे मेगाफोन कंपनी ने बाजार में उतारा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9608dae7-f447-4ff8-9cd9-11d9566c94e1', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यतींद्र मिश्र : पिताजी से संगीत के अलावा आपने क्या-क्या और सीखा? लता मंगेशकर : सबसे ज्यादा तो स्वाभिमान से जीने की प्रेरणा। उन्होंने जो संस्कार दिए उससे जिंदगी में सही बातों पर खड़े रहने की हिम्मत मिली। आज मुझे इस बात की खुशी है कि मैंने किसी से यह नहीं कहा कि आप मुझे पाँच सौ रुपये दीजिए, फलाँ चीज ला दीजिए, मुझे उसकी जरूरत है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0fa5811c-c5b3-4322-88e4-d0c8dde0f225', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इस तरह जो चीज मैं कर पाई, उसमें मैं अपने बाबा का संस्कार मानती हूँ। मैंने पिताजी में यह बात देखी थी कि हर हालात में कैसे रहना चाहिए। यह मेरे पिताजी ने ही मुझे सिखाया था कि अगर कोई बात तुम्हें सही लगती है, तो उसे करो और किसी के$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7ce60292-e4e8-4cf8-b32a-228a3632c45b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरे पिताजी की एक बड़ी विशेषता यह भी थी कि वे एक राग को गाते हुए उसमें सुर बदलकर भी अपना गायन करते थे। मतलब एक राग गाते समय किसी भी सुर को ‘सा’ (षषडज) बनाकर इस तरह राग को बदल देते थे कि वह कुछ नया हो जाता था और फिर उसी समय नए राग में गाते हुए दोबारा से पहले राग और उसके सुर में वापस लौट आते थे। एक नई बात मेरे पिताजी के नाटकों में यह भी थी कि वे पहली बार मराठी रंगमंच में कर्नाटक और पंजाब का संगीत लेकर आए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b234005f-df12-4203-b28e-e2c0ef74f909', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे यह भी याद है कि जिस दिन कोई ड्रामा नहीं होता था, उस दिन घर में संगीत की सभा होती थी और बहुत सारे लोग हमारे घर आते थे। फिर वे उसमें नाटक का कोई गीत नहीं गाते थे, बल्कि उस दिन सिर्फ शास्त्रीय संगीत होता था। मेरे पिताजी के गाए हुए शास्त्रीय संगीत के कई रिकॉर्ड एच.एम.वी. से रिलीज हुए हैं और जहाँ तक मुझे याद पड़ता है कि एक रिकॉर्ड उन्होंने राग जयजयवंती का भी बनाया था, जिसे मेगाफोन कंपनी ने बाजार में उतारा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2dc3c8a9-918c-451e-b90d-800b25902e4b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सबसे ज्यादा तो स्वाभिमान से जीने की प्रेरणा। उन्होंने जो संस्कार दिए उससे जिंदगी में सही बातों पर खड़े रहने की हिम्मत मिली। आज मुझे इस बात की खुशी है कि मैंने किसी से यह नहीं कहा कि आप मुझे पाँच सौ रुपये दीजिए, फलाँ चीज ला दीजिए, मुझे उसकी जरूरत है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ca913370-2718-403e-be9c-9ab2e302d049', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इस तरह जो चीज मैं कर पाई, उसमें मैं अपने बाबा का संस्कार मानती हूँ। मैंने पिताजी में यह बात देखी थी कि हर हालात में कैसे रहना चाहिए। यह मेरे पिताजी ने ही मुझे सिखाया था कि अगर कोई बात तुम्हें सही लगती है, तो उसे करो और किसी के$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('63b33559-511d-4677-b099-ec0ddf84b767', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आगे झुकने की जरूरत नहीं है। इस तरह जब मैं याद करती हूँ, तो लगता है कि बाबा ऐसा कहते थे, बाबा ने यह कहा था, बाबा ने उस समय में इस तरह कोई निर््णय लिया था। यह सब मेरे बड़े काम आया है। हमने हर तरह के दिन देखे थे। पिताजी की कंपनी जब अच्छी चलती थी, तो हम सब लोग बड़े शान से रहते थे। फिर पिताजी के निधन के बाद हमें यह भी देखना पड़ा कि बुरे हालात में कैसे जीना है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('96791e5a-5bda-4433-926b-309b8a8e842d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरी माँ का भी वही संस्कार था कि कैसे भी स््ववाभिमान के साथ जी लेना है, मगर किसी के आगे जाकर हाथ नहीं पसारना है।... और देखिए, ये सब बातें मेरे कितने काम आई हैं। आज मेरे पास पैसे हैं और नाम है। हम आज जहाँ रहते हैं, वह भले ही इतना छोटा-सा घर है, पर उसमें हम लोग बहुत खुश हैं। इस बात के लिए भी ईश्‍वर को धन््यवाद करते हैं कि बाबा ने जैसा सिखाया था, उस पर हम सभी भाई-बहनों ने चलने का प्रयास किया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0a923250-d48d-4cb9-9655-d25b1aa6f5a4', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यतीींद्र मिश्र : बचपन में आप सभी भाई-बहन फिल््में देखकर उसकी नकल उतारते थे। किसी खास फिल््म को देखकर उसकी नकल का स््मरण करेंगी? लता मंगेशकर : (हँसते हुए) अरे! यह तो हम सब भाई-बहन बहुत करते थे। फिल््में ही थीं, जो मनोरंजन का एक ऐसा माध््यम थीं जिनको देखकर बच््चचे अपने ढंग से कुछ-कुछ करते रहते थे। मुझे याद है कि प्रभात फिल््म कंपनी की एक पिक््चर थी ‘संत तुकाराम’।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d96f552c-3bd6-4c32-9253-21d7e292f966', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$फिल््म में दिखाया गया है कि तुकाराम सदेह बैकुंठ जाते हैं और उन््हें लेने ईश्‍वर का विमान आता है। वे यह गीत गाते हुए स््वर््ग जाते हैं— ‘अमी जातो अमचा गावा, अमचा राम-राम ध््ययावा’ (मैं अपने गाँव जा रहा हूँ। सभी लोग मेरा राम-राम ले लीजिए)। हम कमरे में घर भर के गद्दे, तकिये एक के ऊपर एक रखकर ऊँचा स््वर््ग बनाते थे, जिस पर चढ़कर मैं बैठती थी और वहीं से यह गीत गाती थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('29892052-18f0-424d-9be1-177aae485389', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$नीचे कमरे में मीना, मेरे फूफा का बेटा पंढरीनाथ और आशा, ये तीनों तुकाराम के अनुयायी बनकर रोते थे और कहते थे— ‘हमें भी साथ ले लीजिए। हमें भी साथ ले चलिए।’ (खिलखिलाकर हँसती हैं) उस समय उषषा बहुत छोटी थी, इसलिए वह इन नाटकों में नहीं रहती थी। तो यह सब होता था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4588107a-1a1a-437f-b477-6d269fd15c29', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हम बहुत सारी फिल््मों की नकल उतारते थे, जिनमें धार््ममिक फिल््में ज्यादा होती थीं क््योंकि पिताजी धार््ममिक और देशभक््‍तति की फिल््मों के अलावा दूसरी फिल््में नहीं देखने देते थे। उनका सख््त अनुशासन था और यह सब काम चोरी-चोरी तब होता था, जब पिताजी घर के बाहर हों और यह जान न पाएँ कि घर में फिल््मों का खेल खेला जा रहा है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9be0d126-aee8-48bc-bacb-be15047c63f4', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आगे झुकने की जरूरत नहीं है। इस तरह जब मैं याद करती हूँ, तो लगता है कि बाबा ऐसा कहते थे, बाबा ने यह कहा था, बाबा ने उस समय में इस तरह कोई निर््णय लिया था। यह सब मेरे बड़े काम आया है। हमने हर तरह के दिन देखे थे। पिताजी की कंपनी जब अच्छी चलती थी, तो हम सब लोग बड़े शान से रहते थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('06cf8c28-5492-4d8e-8498-8fab0e2fd7fb', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$फिर पिताजी के निधन के बाद हमें यह भी देखना पड़ा कि बुरे हालात में कैसे जीना है। मेरी माँ का भी वही संस्कार था कि कैसे भी स््ववाभिमान के साथ जी लेना है, मगर किसी के आगे जाकर हाथ नहीं पसारना है।... और देखिए, ये सब बातें मेरे कितने काम आई हैं। आज मेरे पास पैसे हैं और नाम है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('29d0b761-2cd2-4e60-aae8-7d06bb9e162c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हम आज जहाँ रहते हैं, वह भले ही इतना छोटा-सा घर है, पर उसमें हम लोग बहुत खुश हैं। इस बात के लिए भी ईश्‍वर को धन््यवाद करते हैं कि बाबा ने जैसा सिखाया था, उस पर हम सभी भाई-बहनों ने चलने का प्रयास किया। यतीींद्र मिश्र : बचपन में आप सभी भाई-बहन फिल््में देखकर उसकी नकल उतारते थे। किसी खास फिल््म को देखकर उसकी नकल का स््मरण करेंगी?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('772e6a90-93bd-496b-ac01-32ab58c2422a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे याद है कि प्रभात फिल््म कंपनी की एक पिक््चर थी ‘संत तुकाराम’। फिल््म में दिखाया गया है कि तुकाराम सदेह बैकुंठ जाते हैं और उन््हें लेने ईश्‍वर का विमान आता है। वे यह गीत गाते हुए स््वर््ग जाते हैं— ‘अमी जातो अमचा गावा, अमचा राम-राम ध््ययावा’ (मैं अपने गाँव जा रहा हूँ। सभी लोग मेरा राम-राम ले लीजिए)। हम कमरे में घर भर के गद्दे, तकिये एक के ऊपर एक रखकर ऊँचा स््वर््ग बनाते थे, जिस पर चढ़कर मैं बैठती थी और वहीं से यह गीत गाती थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('755793f5-f801-493d-8703-5006fc297dd0', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लता मंगेशकर : नहीं, मैंने शुरू में तो फिल््मों में काम ही किया था और कुल छह या सात फिल््मों में किया था। मैं बहुत छोटी थी उस समय, जब फिल््मों की दुनिया में अभिनय के मार्फ़त ही आई।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('74b39d03-f2eb-4fc7-bc59-7e6022405e1c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे कभी अच्छा नहीं लगा मेकअप करना, लाइट के सामने जाना और काफी लोग खड़े हैं, तो उनके सामने कभी रो रहे हैं और कभी हँस रहे हैं। गा भी रहे हैं। मुझे वह कभी अच्छा नहीं लगा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f4bfefa3-9d0f-4f09-b984-68783f348e63', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अच्छी फिल््मों को देखकर सराहने का जी जरूर करता है, मगर अभिनय करने के बारे में तो सोच भी नहीं सकती। एक फिल््म हमारे यहाँ हिंदी और मराठी दोनों में बनी थी ‘छत्रपति शिवाजी’।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('952ad038-a905-42d7-b5eb-09e93519ac07', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उसमें भालजी पेंढारकर थे जिन््हें मैं बाबा कहती थी। मैं उनके पास गई, हालाँकि उस वक्‍त तक मैंने अभिनय का काम छोड़ दिया था। मैंने उनसे खुद कहा—‘बाबा मैं चाहती हूँ कि इस फिल््म का आखिर का जो गाना है, उसमें दो लाइनें मैं भी आकर गाऊँ।’$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('40acf4d8-de3a-4f49-8d3a-109c91a343f0', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तो फिर मैंने उसके हिंदी और मराठी, दोनों ही संस्करणों में बाद की दो पंक््‍ततियाँ गाई हैं, जिन दृश््यों में मैं मौजूद भी हूँ। मैं छत्रपति शिवाजी को बहुत पसंद करती हूँ, इसलिए बस इसी फिल््म के लिए मेरा मन हुआ कि भले ही एक दृश्य में सही, मगर यहाँ रहा जा सकता है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('be3e9eac-b630-4940-aa74-ee9bf1c4885a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यतीींद्र मिश्र : उस दौर में आपके काम की परिस््थथितियाँ कैसी थीं? क्या वे आपके हिसाब से धीरे-धीरे अनुकूल होती गर्इं अथवा वैसे ही हमेशा की तरह एक चुनौती का सबब बनी रहीं, जैसे कि वे संघर््ष के दिनों में थीं?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('adf2e4c1-5865-4784-aa76-923e9869833f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लता मंगेशकर : यह कह पाना मुश््ककिल होगा कि मेरी परिस््थथितियाँ कभी बहुत अच्छी या बुरी रही हों। मैं इन सब बातों पर ध्यान नहीं देती थी। अलबत्ता मैं उस जमाने से लेकर बाद तक बहुत मेहनत से अपने काम करती थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('66ed6936-93bd-4edd-9e19-dd5fb361ba20', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे याद है कि मेरी रेकॉर््डििंंग सुबह से रात तक चलती रहती थी। एक स््टूडियो से दूसरे और तीसरे स््टूडियो के चक्कर में ही पूरा दिन बीत जाता था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('fca15dd3-6bbe-4ff4-bfab-e4c16bd027db', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे अपने गाने और रेकॉर््डििंंग के अलावा किसी दूसरी चीज की सुध नहीं रहती थी। हमेशा यही बात दिमाग में घूमती थी कि किसी तरह बस मुझे अपने परिवार को देखना है। फिर वह रेकॉर््डििंंग का वक्‍त हो या घर का खाली समय। किस तरह मैं अपने परिवार के लिए ज्यादा से ज्यादा कमाकर उनकी जरूरतें पूरी कर सकती हूँ, इसी में सारा वक्‍त निकल जाता था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('372a38da-0963-4f71-910e-ef1d4f9f76bd', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '9fe289e5-a2ca-44f3-acfd-6e40be97dc49', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आप मेरी परिस््थथितियों के बारे में पूछ रहे हैं, तो सच बात तो यही है कि मुझे रेकॉर््डििंंग से या उसकी तकलीफों से इतना फर््क नहीं पड़ता था, जितना इस बात से कि आने वाले कल में मेरे कितने गीत रेकॉर््ड होने हैं। फलाँ फिल््म के खत््म होने के साथ मुझे नए कॉन्ट्ेक्ट की दूसरी नई फिल््मों के गाने कब रेकॉर््ड करने हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-11-897Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
